// /docs, /docs/<slug>.md, /llms.txt, /llms-full.txt and the MCP docs tools.
// The docs content is generated by `npm run docs` (the pretest script).
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { createHash } from 'node:crypto';
import { env } from './cloudflare-workers-stub.mjs';
import { PAGES, unknownIds } from '../scripts/build-docs.mjs';
import { DEPLOY } from '../lib/docs-content.generated.ts';
import * as docs from '../lib/docs.ts';
import { requestTemplates } from '../lib/request-templates.ts';
import * as fairClient from '../../lib/js/fair-client.ts';
import nextConfig from '../next.config.ts';
import { GET as mdRoute } from '../app/docs/md/[slug]/route.ts';
import { GET as assetRoute } from '../app/docs/assets/[file]/route.ts';
import { GET as llmsFullRoute } from '../app/llms-full.txt/route.ts';
import { GET as llmsRoute } from '../app/llms.txt/route.ts';
import { POST as mcp } from '../app/mcp/route.ts';

const repo = (p) => fs.readFileSync(new URL(`../../${p}`, import.meta.url), 'utf8');
const mainnet = JSON.parse(repo('deploy/v3-mainnet.json'));
const siteEnv = Object.fromEntries(repo('site/deploy/native-testnet.env').split(/\r?\n/).filter(Boolean).map((l) => l.split('=')));
Object.assign(env, siteEnv, { RNG_NODE_URL: 'http://node.test' });

const params = (o) => ({ params: Promise.resolve(o) });
const rpc = async (method, p) => (await (await mcp(new Request('http://x/mcp', {
  method: 'POST', body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params: p }) }))).json());
const call = async (name, args = {}) => {
  const { result } = await rpc('tools/call', { name, arguments: args });
  return { ...result, text: result.content[0].text };
};

test('every doc page is generated from docs/, in order, with anchors that resolve', () => {
  assert.deepEqual(docs.docPages.map((p) => p.slug), PAGES.map((p) => p.slug));
  const ids = new Map(docs.docPages.map((p) => [p.slug, new Set([...p.html.matchAll(/ id="([^"]+)"/g)].map((m) => m[1]))]));
  for (const page of docs.docPages) {
    assert.ok(page.title && page.summary && page.html.length > 1000, page.slug);
    assert.ok(page.headings.length > 0, `${page.slug} has a table of contents`);
    for (const [, slug, hash] of page.html.matchAll(/href="\/docs\/([a-z-]+)(?:#([^"]+))?"/g)) {
      if (slug === 'assets' || slug === 'md') continue;
      assert.ok(ids.has(slug.replace(/\.md$/, '')), `${page.slug} links to unknown doc ${slug}`);
      if (hash) assert.ok(ids.get(slug).has(hash), `${page.slug} links to missing #${hash} in ${slug}`);
    }
    for (const [, hash] of page.html.matchAll(/href="#([^"]+)"/g)) assert.ok(ids.get(page.slug).has(hash), `${page.slug}: #${hash}`);
    assert.doesNotMatch(page.html, /href="(?!https?:|\/|#)/, `${page.slug} keeps no repo-relative link`);
  }
});

test('architecture renders its six Mermaid diagrams as the docs/architecture SVGs', async () => {
  const page = docs.getDoc('architecture');
  const srcs = [...page.html.matchAll(/<img src="\/docs\/assets\/([a-z-]+)\.svg"/g)].map((m) => m[1]);
  assert.deepEqual(srcs, ['system-map', 'any-honest-round', 'fast-request', 'fair-session', 'governance', 'money-flows']);
  for (const name of srcs) {
    const res = await assetRoute(new Request('http://x'), params({ file: `${name}.svg` }));
    assert.equal(res.headers.get('content-type'), 'image/svg+xml');
    assert.equal(await res.text(), repo(`docs/architecture/${name}.svg`));
  }
  assert.equal((await assetRoute(new Request('http://x'), params({ file: '../ARCHITECTURE.md' }))).status, 404);
});

test('/docs/<slug>.md rewrites to the markdown route and serves the source markdown', async () => {
  const { beforeFiles } = await nextConfig.rewrites();
  const rule = beforeFiles.find((r) => r.destination === '/docs/md/:slug');
  assert.equal(rule.source, '/docs/:slug([a-z0-9-]+)\\.md');
  for (const page of docs.docPages) {
    const res = await mdRoute(new Request('http://x'), params({ slug: page.slug }));
    assert.equal(res.status, 200);
    assert.match(res.headers.get('content-type'), /^text\/markdown/);
    const text = await res.text();
    assert.ok(text.startsWith(page.markdown.slice(0, 200)));
    assert.match(text, new RegExp(`Source: ${page.source.replace('.', '\\.')}`));
    // Agents get absolute links only.
    assert.doesNotMatch(text.replace(/```[\s\S]*?```/g, ''), /\]\((?!https?:|#|mailto:)/, `${page.slug}.md has a relative link`);
  }
  assert.equal((await mdRoute(new Request('http://x'), params({ slug: 'nope' }))).status, 404);
});

test('/llms.txt indexes every page; /llms-full.txt holds every page', async () => {
  const index = await (await llmsRoute()).text();
  for (const page of docs.docPages) assert.ok(index.includes(`https://randao.net/docs/${page.slug}.md`), page.slug);
  assert.ok(index.includes('https://randao.net/llms-full.txt'));
  for (const id of [mainnet.fast, mainnet.beacon, mainnet.fair, mainnet.token, mainnet.dao]) assert.ok(index.includes(id), id);
  for (const tool of ['rng_status', 'rng_request_plan', 'rng_docs_search', 'rng_request_templates']) assert.ok(index.includes(tool), tool);
  const full = await (await llmsFullRoute()).text();
  for (const page of docs.docPages) assert.ok(full.includes(page.markdown), page.slug);
});

test('the site env and the docs name the ids in deploy/v3-mainnet.json', () => {
  assert.equal(siteEnv.RNG_BEACON_ID, mainnet.fast, 'RNG_BEACON_ID is the Fast tier');
  assert.equal(siteEnv.RNG_ANYHONEST_ID, mainnet.beacon);
  assert.equal(siteEnv.RNG_TOKEN_ID, mainnet.token);
  assert.equal(siteEnv.RNG_DAO_ID, mainnet.dao);
  assert.equal(siteEnv.RNG_FAIR_ID, mainnet.fair);
  assert.deepEqual([DEPLOY.fast, DEPLOY.anyHonest, DEPLOY.fair, DEPLOY.token], [mainnet.fast, mainnet.beacon, mainnet.fair, mainnet.token]);
  const use = docs.getDoc('use').markdown;
  for (const id of [mainnet.fast, mainnet.beacon, mainnet.fair, mainnet.token, mainnet.scheduler]) assert.ok(use.includes(id), id);
});

test('docs search finds sections and reads them back', () => {
  const hits = docs.searchDocs('Request-Random Tier');
  assert.ok(hits.length > 0);
  assert.ok(hits.some((h) => h.slug === 'use'));
  for (const h of hits) assert.ok(docs.readDoc(h.slug, h.section || undefined), `${h.slug}#${h.section}`);
  assert.deepEqual(docs.searchDocs('  '), []);
  assert.deepEqual(docs.searchDocs('zzzz-not-a-word'), []);
  const section = docs.readDoc('use', 'fair-play-for-games');
  assert.match(section.markdown, /^## Fair play for games/);
  assert.match(section.markdown, /Fair\.Commit/);
  assert.equal(docs.readDoc('use', 'nope'), null);
});

// Each template's Action and tags must exist in the code of the process it targets.
const sources = {
  [mainnet.token]: repo('protocol/token/rng-token.lua'),
  [mainnet.fast]: repo('protocol/beacon/beacon.lua'),
  [mainnet.beacon]: repo('protocol/beacon/anyhonest.lua'),
  [mainnet.fair]: repo('lib/fair.lua') + repo('protocol/fair/fair.lua'),
};
const handles = (src, action) => src.includes(`H["${action}"]`) || src.includes(`a == "${action.toLowerCase()}"`);
const reads = (src, tag) => src.includes(`msg["${tag}"]`) || src.includes(`msg.${tag}`);

test('request templates match the protocol code and lib/js helpers', () => {
  const ids = { token: mainnet.token, fast: mainnet.fast, anyHonest: mainnet.beacon, fair: mainnet.fair };
  const out = requestTemplates(ids, { unit: 1_000_000, fast: { request: 3 }, anyHonest: { request: 4, subscription: 1, subscriptionRounds: 1000 }, fairRequestAtoms: 4_000_000 });
  const byId = Object.fromEntries(out.templates.map((t) => [t.id, t]));
  for (const t of out.templates) {
    if (t.tier === 'local') continue;
    const src = sources[t.target];
    assert.ok(src, `${t.id}: unknown target ${t.target}`);
    assert.ok(handles(src, t.tags.Action), `${t.id}: ${t.tags.Action} is not handled`);
    for (const tag of Object.keys(t.tags).filter((k) => k !== 'Action')) {
      // A Transfer's X- tags ride on the Credit-Notice to the recipient.
      const where = tag.startsWith('X-') ? sources[t.tags.Recipient] : src;
      assert.ok(reads(where, tag), `${t.id}: ${tag} is never read`);
    }
  }
  assert.ok(handles(sources[mainnet.fast], 'Credit-Notice') && handles(sources[mainnet.beacon], 'Credit-Notice'));
  // The same shapes as lib/js.
  const { Action, Recipient, Quantity, 'X-Request-Id': rid } = byId['any-honest.pay-and-request'].tags;
  assert.deepEqual({ Action, Recipient, Quantity, 'X-Request-Id': rid }, { ...fairClient.payAndRequestTags(mainnet.beacon, 4_000_000n, rid) });
  assert.equal(byId['fast.pay-and-request'].tags.Quantity, '3000000');
  const fund = fairClient.fairFundTags(mainnet.fair, mainnet.subscriptionConsumer, 4_000_000n);
  assert.deepEqual({ ...byId['fair.fund'].tags, 'X-Fair-Game': fund['X-Fair-Game'] }, fund);
  assert.deepEqual(Object.keys(byId['fair.commit'].tags), Object.keys(fairClient.fairCommitTags('g', 's', 'c')));
  assert.deepEqual(Object.keys(byId['fair.open'].tags), Object.keys(fairClient.fairOpenTags('s', 'p')));
  assert.deepEqual(Object.keys(byId['fair.reveal'].tags), Object.keys(fairClient.fairRevealTags('g', 's', 'x', 'p')));
  assert.deepEqual(Object.keys(byId['fair.expire'].tags), Object.keys(fairClient.fairExpireTags('g', 's', 'p')));
  // Tier names the processes accept.
  assert.match(sources[mainnet.fast], /tier ~= "fast" and tier ~= "beacon"/);
  assert.match(sources[mainnet.beacon], /tier ~= "any-honest" and tier ~= "timelock"/);
  assert.equal(byId['fast.request'].tags.Tier, 'fast');
  assert.equal(byId['any-honest.request'].tags.Tier, 'any-honest');
});

test('MCP keeps its tools and adds the docs and template tools', async () => {
  const { result } = await rpc('tools/list');
  const names = result.tools.map((t) => t.name);
  for (const n of ['rng_status', 'rng_verify_round', 'rng_anyhonest_status', 'rng_governance_status', 'rng_derive',
    'rng_integration_guide', 'rng_request_plan', 'rng_docs_list', 'rng_docs_read', 'rng_docs_search', 'rng_request_templates']) {
    assert.ok(names.includes(n), n);
  }
  const listed = JSON.parse((await call('rng_docs_list')).text);
  assert.deepEqual(listed.map((d) => d.slug), PAGES.map((p) => p.slug));
  const page = await call('rng_docs_read', { slug: 'whitepaper' });
  assert.match(page.text, /^# RNG v3/);
  const section = await call('rng_docs_read', { slug: 'use', section: 'any-honest' });
  assert.match(section.text, /^## Any-Honest/);
  assert.equal((await call('rng_docs_read', { slug: 'use', section: 'missing' })).isError, true);
  const hits = JSON.parse((await call('rng_docs_search', { query: 'Fair.Withdraw Nonce', limit: 3 })).text);
  assert.ok(hits.length >= 1 && hits.length <= 3);
  assert.equal((await call('rng_docs_search', { query: '' })).isError, true);
  // Existing tools still answer (no network needed).
  const guide = await call('rng_integration_guide', { language: 'lua' });
  assert.match(guide.text, new RegExp(mainnet.fast));
  const derived = JSON.parse((await call('rng_derive', { seed: 'abc', bytes: 4 })).text);
  assert.equal(derived.bytes, 4);
});

test('rng_request_templates reads live prices, and falls back to the genesis defaults', async () => {
  const realFetch = globalThis.fetch;
  try {
    const json = (v) => new Response(JSON.stringify(v));
    globalThis.fetch = async (url) => {
      const u = String(url);
      if (u.includes(`${mainnet.fast}~process@1.0/now/beaconinfo`)) return json({ price: { fast: 5, beacon: 5 }, unit: 1_000_000 });
      if (u.includes(`${mainnet.beacon}~process@1.0/now/beaconinfo`)) return json({ unit: 1_000_000, priceSchedule: { request: 6, subscription: 2, subscriptionRounds: 500 } });
      if (u.includes(`${mainnet.fair}~process@1.0/now/fairinfo`)) return json({ requestPriceAtoms: 6_000_000 });
      return new Response('', { status: 404 });
    };
    const live = JSON.parse((await call('rng_request_templates')).text);
    assert.equal(live.network, 'Mainnet');
    assert.deepEqual([live.ids.fast, live.ids.anyHonest, live.ids.fair, live.ids.token], [mainnet.fast, mainnet.beacon, mainnet.fair, mainnet.token]);
    assert.equal(live.idsDifferFromDeployFile, undefined);
    assert.deepEqual(live.priceSource, { fast: 'live', anyHonest: 'live', fair: 'live' });
    const t = Object.fromEntries(live.templates.map((x) => [x.id, x]));
    assert.equal(t['fast.pay-and-request'].tags.Quantity, '5000000');
    assert.equal(t['any-honest.pay-and-request'].tags.Quantity, '6000000');
    assert.equal(t['any-honest.subscribe'].tags.Rounds, '500');
    assert.equal(t['fair.fund'].tags.Quantity, '6000000');
    globalThis.fetch = async () => { throw new TypeError('offline'); };
    const fallback = JSON.parse((await call('rng_request_templates')).text);
    assert.deepEqual(fallback.priceSource, { fast: 'default', anyHonest: 'default', fair: 'default' });
    const f = Object.fromEntries(fallback.templates.map((x) => [x.id, x]));
    assert.equal(f['fast.pay-and-request'].tags.Quantity, '3000000');
    assert.equal(f['any-honest.pay-and-request'].tags.Quantity, '4000000');
  } finally {
    globalThis.fetch = realFetch;
  }
});

test('the generator flags a doc id that deploy/v3-mainnet.json does not know', () => {
  const fake = createHash('sha256').update('x').digest('base64url').slice(0, 43);
  assert.deepEqual(unknownIds(`Fast \`${mainnet.fast}\`, retired ${mainnet.retired[0].pid}, new ${fake}.`, mainnet), [fake]);
  for (const page of PAGES) assert.deepEqual(unknownIds(repo(page.source), mainnet), [], page.source);
});
